package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A sheet's period: a name unique on the sheet and an inclusive from and to date; whether it is closed, and
 *  the due-total fixed when it was closed (null while open); and whether it is soft-closed: its due-total (and each
 *  person's) fixed as a close fixes them, while its claims can still be changed (never both closed and soft). */
public record Period(String sheetId, String name, LocalDate from, LocalDate to, boolean closed,
        BigDecimal closedTotal, boolean soft) {

    /** Whether this period shares a day with the dates from..to (inclusive). */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }

    /** Whether the date falls in this period. */
    public boolean contains(LocalDate date) {
        return overlaps(date, date);
    }
}
package net.officefloor.hq.app.period;

/** Body of a period add: who is making it, the name, and the from and to dates (yyyy-mm-dd). */
public record PeriodRequest(String user, String name, String from, String to) {
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;

/** A validated period add: who is making it, the trimmed name, and the from and to dates (from on or before to). */
public record PeriodInput(String user, String name, LocalDate from, LocalDate to) {
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

/** Refuse a period whose name another period on the sheet already has (without regard to case), or whose
 *  dates overlap another period's. */
public class ValidateNewPeriod {
    public void validate(@PathVariable("sheetId") String sheetId, @Val PeriodInput input,
            PeriodRepository repository) throws InvalidPeriodException {
        String id = sheetId.trim();
        repository.lockSheet(id);
        for (Period p : repository.list(id)) {
            if (p.name().trim().equalsIgnoreCase(input.name())) {
                throw new InvalidPeriodException("The period name " + input.name() + " is already in use on this sheet.");
            }
            if (p.overlaps(input.from(), input.to())) {
                throw new InvalidPeriodException("The dates overlap the period " + p.name() + ".");
            }
        }
    }
}
package net.officefloor.hq.app.period;

import java.time.LocalDate;
import java.time.format.DateTimeParseException;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Bind the body and refuse it before anything is read or written: a name, from and to real yyyy-mm-dd dates,
 *  from on or before to. */
public class ValidatePeriod {
    public void validate(@RequestBody PeriodRequest request, Out<PeriodInput> body) throws InvalidPeriodException {
        if (request == null || request.user() == null || request.user().isBlank()) {
            throw new InvalidPeriodException("Sign in before adding periods.");
        }
        String name = request.name() == null ? "" : request.name().trim();
        if (name.isEmpty() || name.length() > 200) {
            throw new InvalidPeriodException("The period needs a name.");
        }
        LocalDate from = date(request.from(), "from");
        LocalDate to = date(request.to(), "to");
        if (from.isAfter(to)) {
            throw new InvalidPeriodException("The from-date must be on or before the to-date.");
        }
        body.set(new PeriodInput(request.user().trim(), name, from, to));
    }

    private static LocalDate date(String text, String which) throws InvalidPeriodException {
        try {
            return LocalDate.parse(text == null ? "" : text.trim());
        } catch (DateTimeParseException e) {
            throw new InvalidPeriodException("The " + which + "-date must be a date, yyyy-mm-dd.");
        }
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;
import org.springframework.web.bind.annotation.PathVariable;

public class SaveNewPeriod {
    public void save(@PathVariable("sheetId") String sheetId, @Val PeriodInput input,
            PeriodRepository repository, Out<Period> period) {
        period.set(repository.insert(sheetId.trim(), input.name(), input.from(), input.to()));
    }
}
package net.officefloor.hq.app.period;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Record the stored add in the audit file. */
public class AuditPeriodAdded {
    public void audit(@Val PeriodInput input, @Val Period period, Audit audit) {
        audit.record("PERIOD_ADDED sheet=" + period.sheetId() + " by=" + input.user()
                + " period=" + period.name() + " from=" + period.from() + " to=" + period.to());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.util.Map;
import java.util.TreeMap;

/** A period as the screen shows it: the name, the from and to dates (yyyy-mm-dd), whether it is closed, the
 *  due-total fixed when it was closed (null while open), and each person's due-total fixed then, by person id
 *  (empty while open), and whether it is soft-closed (its figures fixed as for a closed one). */
public record PeriodResponse(String name, String from, String to, boolean closed, String closedTotal,
        Map<Long, String> personTotals, boolean soft) {
    public static PeriodResponse from(Period p, Map<Long, BigDecimal> personTotals) {
        Map<Long, String> shown = new TreeMap<>();
        if ((p.closed() || p.soft()) && personTotals != null) {
            personTotals.forEach((id, total) -> shown.put(id, total.toPlainString()));
        }
        return new PeriodResponse(p.name(), p.from().toString(), p.to().toString(), p.closed(),
                p.closedTotal() != null ? p.closedTotal().toPlainString() : null, shown, p.soft());
    }
}
package net.officefloor.hq.app.period;

import java.math.BigDecimal;
import java.sql.Date;
import java.time.LocalDate;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.stereotype.Repository;

/** Periods by sheet, earliest first. */
@Repository
public class PeriodRepository {

    private static final RowMapper<Period> ROW = (rs, i) -> new Period(rs.getString("sheet_id"),
            rs.getString("name"), rs.getObject("from_date", LocalDate.class), rs.getObject("to_date", LocalDate.class),
            rs.getBoolean("closed"), rs.getBigDecimal("closed_total"), rs.getBoolean("soft"));

    private final JdbcTemplate jdbc;

    public PeriodRepository(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    public List<Period> list(String sheetId) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? ORDER BY from_date", ROW, sheetId);
    }

    /** Lock the sheet's row until the transaction ends, so concurrent period adds are checked one after the other. */
    public void lockSheet(String sheetId) {
        jdbc.query("SELECT id FROM sheet WHERE id = ? FOR UPDATE", rs -> null, sheetId);
    }

    public Period insert(String sheetId, String name, LocalDate from, LocalDate to) {
        jdbc.update("INSERT INTO period (sheet_id, name, from_date, to_date, added_on) VALUES (?, ?, ?, ?, "
                + "(SELECT today FROM sheet WHERE id = ?))", sheetId, name, Date.valueOf(from), Date.valueOf(to), sheetId);
        return new Period(sheetId, name, from, to, false, null, false);
    }

    /** The period on the sheet with this name (without regard to case or surrounding spaces), or null. */
    public Period find(String sheetId, String name) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND name_key = LOWER(TRIM(?))", ROW, sheetId, name)
                .stream().findFirst().orElse(null);
    }

    /** The closed period on the sheet whose dates contain the date, or null when none does. */
    public Period closedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.closed() && p.contains(date)).findFirst().orElse(null);
    }

    /** The soft-closed period on the sheet whose dates contain the date, or null when none does. */
    public Period softClosedOn(String sheetId, LocalDate date) {
        return list(sheetId).stream().filter(p -> p.soft() && p.contains(date)).findFirst().orElse(null);
    }

    /** Close the period (open or soft-closed), fixing its due-total and each person's (by person id) afresh: false
     *  when it was already closed, and nothing is written. */
    public boolean close(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals) {
        if (jdbc.update("UPDATE period SET closed = TRUE, soft = FALSE, closed_total = ? WHERE sheet_id = ? AND name = ? AND NOT closed",
                total, period.sheetId(), period.name()) != 1) {
            return false;
        }
        fixPersonTotals(period, personTotals);
        kept(period);
        return true;
    }

    /** Soft-close the open period, fixing its due-total and each person's (by person id): false when it was already
     *  closed or soft-closed, and nothing is written. */
    public boolean softClose(Period period, BigDecimal total, Map<Long, BigDecimal> personTotals) {
        if (jdbc.update("UPDATE period SET soft = TRUE, closed_total = ? WHERE sheet_id = ? AND name = ? AND NOT closed AND NOT soft",
                total, period.sheetId(), period.name()) != 1) {
            return false;
        }
        fixPersonTotals(period, personTotals);
        kept(period);
        return true;
    }

    private void fixPersonTotals(Period period, Map<Long, BigDecimal> personTotals) {
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", period.sheetId(), period.name());
        personTotals.forEach((personId, personTotal) -> jdbc.update(
                "INSERT INTO period_person_total (sheet_id, period_name, person_id, total) VALUES (?, ?, ?, ?)",
                period.sheetId(), period.name(), personId, personTotal));
    }

    /** The people's due-totals fixed in the sheet's closed periods: by period name, then by person id. */
    public Map<String, Map<Long, BigDecimal>> personTotals(String sheetId) {
        Map<String, Map<Long, BigDecimal>> totals = new HashMap<>();
        jdbc.query("SELECT period_name, person_id, total FROM period_person_total WHERE sheet_id = ?", rs -> {
            totals.computeIfAbsent(rs.getString("period_name"), k -> new HashMap<>())
                    .put(rs.getLong("person_id"), rs.getBigDecimal("total"));
        }, sheetId);
        return totals;
    }

    /** Reopen the closed or soft-closed period, dropping its fixed due-totals: false when it was neither, and nothing
     *  is written. */
    public boolean reopen(Period period) {
        if (jdbc.update("UPDATE period SET closed = FALSE, soft = FALSE, closed_total = NULL WHERE sheet_id = ? AND name = ? AND (closed OR soft)",
                period.sheetId(), period.name()) != 1) {
            return false;
        }
        jdbc.update("DELETE FROM period_person_total WHERE sheet_id = ? AND period_name = ?", period.sheetId(), period.name());
        kept(period);
        return true;
    }

    /** Date the period's latest kept history (an auto close: the day its grace ran out, not the new today). */
    public void dateLastKept(Period period, LocalDate madeOn) {
        jdbc.update("UPDATE period_history SET made_on = ? WHERE id = (SELECT MAX(id) FROM period_history "
                + "WHERE sheet_id = ? AND period_name = ?)", madeOn, period.sheetId(), period.name());
    }

    /** Keep the period as it stands now (closed or soft-closed, and its fixed due-totals) in its history, with the
     *  sheet's today. */
    private void kept(Period period) {
        var keys = new org.springframework.jdbc.support.GeneratedKeyHolder();
        jdbc.update(con -> {
            var ps = con.prepareStatement("INSERT INTO period_history (sheet_id, period_name, closed, soft, closed_total, "
                    + "made_on) SELECT p.sheet_id, p.name, p.closed, p.soft, p.closed_total, s.today FROM period p "
                    + "JOIN sheet s ON s.id = p.sheet_id WHERE p.sheet_id = ? AND p.name = ?", new String[] { "id" });
            ps.setString(1, period.sheetId());
            ps.setString(2, period.name());
            return ps;
        }, keys);
        jdbc.update("INSERT INTO period_history_total (history_id, person_id, total) SELECT ?, person_id, total "
                + "FROM period_person_total WHERE sheet_id = ? AND period_name = ?", keys.getKey().longValue(),
                period.sheetId(), period.name());
    }

    /** A period as it stood at the end of a day, with the people's due-totals fixed in it then, by person id. */
    public record PeriodThen(Period period, Map<Long, BigDecimal> personTotals) {
    }

    /** The sheet's periods as they stood at the end of the day, earliest first: those added while the sheet's today
     *  was on or before it (or before history was kept), each closed or soft-closed as its last close, soft-close or
     *  reopen made by then left it (open when none was). */
    public List<PeriodThen> listAsOf(String sheetId, LocalDate end) {
        return jdbc.query("SELECT * FROM period WHERE sheet_id = ? AND (added_on IS NULL OR added_on <= ?) "
                + "ORDER BY from_date", ROW, sheetId, end).stream().map(p -> {
                    var last = jdbc.queryForList("SELECT id, closed, soft, closed_total FROM period_history "
                            + "WHERE sheet_id = ? AND period_name = ? AND (made_on IS NULL OR made_on <= ?) "
                            + "ORDER BY id DESC LIMIT 1", sheetId, p.name(), end);
                    if (last.isEmpty()) {
                        return new PeriodThen(new Period(sheetId, p.name(), p.from(), p.to(), false, null, false), Map.of());
                    }
                    var row = last.get(0);
                    Map<Long, BigDecimal> totals = new HashMap<>();
                    jdbc.query("SELECT person_id, total FROM period_history_total WHERE history_id = ?", rs -> {
                        totals.put(rs.getLong(1), rs.getBigDecimal(2));
                    }, row.get("id"));
                    return new PeriodThen(new Period(sheetId, p.name(), p.from(), p.to(), Boolean.TRUE.equals(row.get("closed")),
                            (BigDecimal) row.get("closed_total"), Boolean.TRUE.equals(row.get("soft"))), totals);
                }).toList();
    }
}
-- The sheet's periods: a name unique on the sheet (compared without regard to case, ignoring surrounding
-- spaces) and an inclusive from and to date. No two periods on a sheet overlap. A claim belongs to the
-- period whose dates contain its date, or to none.
CREATE TABLE period (
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    name      VARCHAR(200) NOT NULL,
    name_key  VARCHAR(200) GENERATED ALWAYS AS (LOWER(TRIM(name))),
    from_date DATE         NOT NULL,
    to_date   DATE         NOT NULL,
    CHECK (from_date <= to_date)
);
CREATE UNIQUE INDEX period_sheet_name ON period(sheet_id, name_key);
-- Each SNAPSHOT written for a person when the sheet's today changes: the day being left and their due-total on it
-- (two decimals, or n/a), in the order written (by id).
CREATE TABLE person_snapshot (
    id        BIGINT AUTO_INCREMENT PRIMARY KEY,
    sheet_id  VARCHAR(100) NOT NULL REFERENCES sheet(id),
    person_id BIGINT       NOT NULL,
    left_on   DATE         NOT NULL,
    due_total VARCHAR(20)  NOT NULL
);
CREATE INDEX person_snapshot_sheet ON person_snapshot(sheet_id, person_id, id);

